// Simple endless‑runner game based on IDEA.md
// Canvas element with id="game" must exist in the HTML.
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas #game not found');
  const ctx = canvas.getContext('2d');
  // Set canvas dimensions (fallback to 800×600)
  canvas.width = canvas.width || 800;
  canvas.height = canvas.height || 600;

  const PLAYER_SIZE = 30;
  const PLAYER_SPEED = 4;
  const DEBRIS_SIZE = 20;
  const DEBRIS_SPEED = 3;
  const SPAWN_INTERVAL = 1500; // ms
  const MAX_SHIELDS = 3;

  const player = {
    x: canvas.width / 5,
    y: canvas.height / 2 - PLAYER_SIZE / 2,
    w: PLAYER_SIZE,
    h: PLAYER_SIZE,
    shields: MAX_SHIELDS,
  };

  const keys = { ArrowUp: false, ArrowDown: false, ArrowLeft: false, ArrowRight: false, w: false, a: false, s: false, d: false };
  window.addEventListener('keydown', e => {
    if (e.key in keys) keys[e.key] = true;
  });
  window.addEventListener('keyup', e => {
    if (e.key in keys) keys[e.key] = false;
  });

  const debris = [];
  let lastSpawn = 0;
  let gameOver = false;

  function spawnDebris() {
    const y = Math.random() * (canvas.height - DEBRIS_SIZE);
    debris.push({ x: canvas.width, y, w: DEBRIS_SIZE, h: DEBRIS_SIZE });
  }

  function update(dt) {
    // player movement
    if (keys.ArrowUp || keys.w) player.y -= PLAYER_SPEED;
    if (keys.ArrowDown || keys.s) player.y += PLAYER_SPEED;
    if (keys.ArrowLeft || keys.a) player.x -= PLAYER_SPEED;
    if (keys.ArrowRight || keys.d) player.x += PLAYER_SPEED;
    // keep inside canvas
    player.x = Math.max(0, Math.min(canvas.width - player.w, player.x));
    player.y = Math.max(0, Math.min(canvas.height - player.h, player.y));

    // debris movement
    for (let i = debris.length - 1; i >= 0; i--) {
      const d = debris[i];
      d.x -= DEBRIS_SPEED;
      // collision detection
      if (
        d.x < player.x + player.w &&
        d.x + d.w > player.x &&
        d.y < player.y + player.h &&
        d.y + d.h > player.y
      ) {
        player.shields--;
        debris.splice(i, 1);
        if (player.shields <= 0) {
          gameOver = true;
        }
        continue;
      }
      // remove off‑screen debris
      if (d.x + d.w < 0) debris.splice(i, 1);
    }

    // spawn new debris
    if (performance.now() - lastSpawn > SPAWN_INTERVAL) {
      spawnDebris();
      lastSpawn = performance.now();
    }
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    // background (simple dark space)
    ctx.fillStyle = '#000020';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    // player ship (white triangle)
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.moveTo(player.x, player.y + player.h / 2);
    ctx.lineTo(player.x + player.w, player.y);
    ctx.lineTo(player.x + player.w, player.y + player.h);
    ctx.closePath();
    ctx.fill();
    // debris (red squares)
    ctx.fillStyle = '#f44';
    debris.forEach(d => {
      ctx.fillRect(d.x, d.y, d.w, d.h);
    });
    // shields display
    ctx.fillStyle = '#0f0';
    ctx.font = '16px sans-serif';
    ctx.fillText('Shields: ' + player.shields, 10, 20);
  }

  let lastTime = 0;
  function loop(timestamp) {
    if (!lastTime) lastTime = timestamp;
    const dt = timestamp - lastTime;
    lastTime = timestamp;
    if (!gameOver) {
      update(dt);
      draw();
      requestAnimationFrame(loop);
    } else {
      ctx.fillStyle = '#f88';
      ctx.font = '48px sans-serif';
      ctx.fillText('Game Over', canvas.width / 2 - 120, canvas.height / 2);
    }
  }

  requestAnimationFrame(loop);
})();
